global class OverdueInvoiceBatch implements Database.Batchable<SObject> {
    private Integer updatedCount = 0;
    private Integer failedCount = 0;
    private Decimal overdueAmount = 0;

    global OverdueInvoiceBatch() {}

    global Database.QueryLocator start(Database.BatchableContext bc) {
        return Database.getQueryLocator([
            SELECT Id, Name, Status__c, Due_Date__c, Amount__c, Customer_Email__c
            FROM FB_Invoice__c
            WHERE Status__c = 'Open'
            AND Due_Date__c < TODAY
        ]);
    }

    global void execute(Database.BatchableContext bc, List<SObject> batch) {
        for (SObject s : batch) {
            FB_Invoice__c inv = (FB_Invoice__c) s;
            inv.Status__c = 'Overdue';
            try {
                update inv;
                updatedCount++;
                overdueAmount += (inv.Amount__c == null ? 0 : inv.Amount__c);
            } catch (Exception e) {
                failedCount++;
            }
        }
    }

    global void finish(Database.BatchableContext bc) {
        FB_Job_Summary__c summary = new FB_Job_Summary__c();
        summary.Job_Name__c = 'OverdueInvoiceBatch';
        summary.Records_Updated__c = updatedCount;
        summary.Records_Failed__c = failedCount;
        summary.Overdue_Amount__c = overdueAmount;
        insert summary;
    }
}
```

**Why this works:**

| Concern | Approach |
|---|---|
| **Individual failure isolation** | `try/catch` around each `update` ensures a validation-rule failure (e.g. blank `Customer_Email__c`) is caught and counted without aborting the remaining records in the chunk. This is the standard Salesforce-recommended pattern for batch operations where per-record failure handling is needed. |
| **Cross-chunk totals** | Instance fields initialised in the no-arg constructor accumulate across every `execute` call regardless of batch size. |
| **Null-safe amount** | `inv.Amount__c == null ? 0 : inv.Amount__c` treats blank amounts as zero. |
| **Direct-call compatibility** | `bc` is never dereferenced, so `start(null)`, `execute(null, list)`, `finish(null)` all work. |
| **Exactly one summary row** | `finish` inserts one `FB_Job_Summary__c`, called once per job. |
| **Compile safety** | Uses only `update` (DML statement) — no dependency on `Database.saveRecords` signature. |

