public class ErpSyncFinalizer implements Finalizer {
    private Set<Id> accountIds;
    private Integer attempt;

    public ErpSyncFinalizer(Set<Id> accountIds, Integer attempt) {
        this.accountIds = accountIds;
        this.attempt = attempt;
    }

    public void execute(FinalizerContext context) {
        FB_Job_Log__c jobLog = new FB_Job_Log__c(
            Job_Name__c = 'ErpAccountSyncJob',
            Attempt__c = attempt
        );

        Exception ex = context.getException();
        if (ex == null) {
            jobLog.Status__c = 'Success';
        } else {
            jobLog.Status__c = 'Failed';
            String errorMsg = ex.getMessage();
            if (errorMsg != null && errorMsg.length() > 255) {
                errorMsg = errorMsg.left(255);
            }
            jobLog.Error__c = errorMsg;

            if (attempt < 3) {
                System.enqueueJob(new ErpAccountSyncJob(accountIds, attempt + 1));
            }
        }

        insert jobLog;
    }
}
