        // UnitOfWork – register a UoW factory per SObject type.
        // The Account UoW carries the FK links so a single commit can insert
        // new Accounts, their Contacts & Opportunities, and OpportunityContactRoles.
        UnitOfWork.registerUow(Account.SObjectType, new AccountUoWFactory());
        UnitOfWork.registerUow(Contact.SObjectType, new ContactUoWFactory());
        UnitOfWork.registerUow(Opportunity.SObjectType, new OpportunityUoWFactory());
        UnitOfWork.registerUow(OpportunityContactRole.SObjectType, new OCRUoWFactory());

        // Service
        Service.registerService(IAccountsService.class, (Object) new AccountsServiceImpl());

        // Selector
        Selector.registerSelector(Account.SObjectType, (fflib_ISObjectSelector) new AccountsSelector());
        Selector.registerSelector(Contact.SObjectType, (fflib_ISObjectSelector) new ContactsSelector());

        // Domain
        Domain.registerDomain(Account.SObjectType, (fflib_SObjectDomain.IConstructable) new Accounts.Constructor());
    }

