        public override fflib_ISObjectUnitOfWork newUnitOfWork() {
            fflib_SObjectUnitOfWork uow = new fflib_SObjectUnitOfWork(Account.SObjectType);
            uow.registerFKLink(Contact.AccountId, Account.Id, Account.SObjectType);
            uow.registerFKLink(Opportunity.AccountId, Account.Id, Account.SObjectType);
            uow.registerFKLink(OpportunityContactRole.OpportunityId, Opportunity.Id, Opportunity.SObjectType);
