```apex
public class CaseSurveyJob implements Queueable {

    private Id       caseId;
    private List<Id> caseIds;

    /**
     * Single-case constructor – used by the trigger for <= 50 cases.
     */
    public CaseSurveyJob(Id caseId) {
        this.caseId = caseId;
    }

    /**
     * List constructor – used by the trigger when > 50 cases are eligible
     * in one transaction (exceeds the 50-job enqueue limit).
     */
    public CaseSurveyJob(List<Id> caseIds) {
        this.caseIds = caseIds;
    }

    public void execute(QueueableContext ctx) {
        if (caseId != null) {
            processSingleCase(caseId);
        } else if (caseIds != null && !caseIds.isEmpty()) {
            processBulk(caseIds);
        }
    }

    // -----------------------------------------------------------------------
    // Single-case path: full transaction isolation (one job = one case).
    // -----------------------------------------------------------------------
    private void processSingleCase(Id cId) {
        Case c = [
            SELECT Id, CaseNumber, ContactId
            FROM Case
            WHERE Id = :cId
        ];

        // Re-check in case the contact was removed after the trigger fired.
        if (c.ContactId == null) {
            return;
        }

        insert new Task(
            WhatId       = c.Id,
            WhoId        = c.ContactId,
            Subject      = 'CSAT survey: ' + c.CaseNumber,
            ActivityDate = Date.today().addDays(2),
            Status       = 'Not Started'
        );
    }

    // -----------------------------------------------------------------------
    // Bulk path: one SOQL, one DML.  Non-bulk DML mode ensures that a
    // validation error on one record does not prevent the others from being
    // inserted.
    // -----------------------------------------------------------------------
    private void processBulk(List<Id> ids) {
        Map<Id, Case> caseMap = new Map<Id, Case>(
            [SELECT Id, CaseNumber, ContactId FROM Case WHERE Id IN :ids]
        );

        List<Task> tasks = new List<Task>();
        for (Id id : ids) {
            Case c = caseMap.get(id);
            if (c == null || c.ContactId == null) {
                continue;
            }
            tasks.add(new Task(
                WhatId       = c.Id,
                WhoId        = c.ContactId,
                Subject      = 'CSAT survey: ' + c.CaseNumber,
                ActivityDate = Date.today().addDays(2),
                Status       = 'Not Started'
            ));
        }

        if (!tasks.isEmpty()) {
            // false = non-bulk: individual record failures do not affect others
            Database.insert(tasks, false);
        }
    }
}
