import Account_Selected__c from '@salesforce/messageContext/Account_Selected__c';

export default class AccountDetailsPanel extends LightningElement {
    @wire(MessageContext) messageContext;

    @track selectedRecordId;
    _subscription;

    connectedCallback() {
        this.registerSubscription();
    }

    disconnectedCallback() {
        this.unsubscribe();
    }

    registerSubscription() {
        if (!this._subscription) {
            this.messageContext.subscribe(
                {
                    template: Account_Selected__c,
                    scope: APPLICATION_SCOPE
                },
                (message) => {
                    this.handleMessage(message);
                }
            ).then((subscription) => {
                this._subscription = subscription;
            });
        }
    }

    unsubscribe() {
        if (this._subscription) {
            const subscription = this._subscription;
            this._subscription = undefined;
            this.messageContext.unsubscribe(subscription);
        }
    }

    handleMessage(message) {
        this.selectedRecordId = message.recordId || null;
    }

    handleClear(event) {
        if (event.target.dataset.action === 'clear') {
            this.messageContext.publish({
                template: Account_Selected__c,
                data: { recordId: null }
            });
        }
    }
}
