const contextInstance = {
    subscribe: jest.fn((template, callback) => {
        const id = nextId++;
        subscriptions.set(id, { template, callback });
        return Promise.resolve(id);
    }),
    unsubscribe: jest.fn((id) => {
        subscriptions.delete(id);
    }),
